// Generated by tack build. Do not edit. The hook client owns the daemon
// connection; this extension only translates calls and fails closed.

import { spawn } from "node:child_process";
import { appendFileSync } from "node:fs";

const HOOK_BIN = "tack-hook";
const PLUGIN_DIR = __TACK_PLUGIN_DIR__;
const PROTOCOL_VERSION = __TACK_PROTOCOL_VERSION__;
const BUDGET_MS = __TACK_BUDGET_MS__;
const MAX_FRAME_BYTES = __TACK_MAX_FRAME_BYTES__;
const DENY_REASONS = __TACK_DENY_REASONS__;

const STATUS = "guard_status: daemon ok";
const REASONS = new Set(DENY_REASONS);

function refuse(reason) {
  return { ok: false, reason };
}

function readReply(request, chunks, size) {
  const malformed = refuse("malformed_reply");
  let reply;

  try {
    const text = new TextDecoder("utf-8", { fatal: true })
      .decode(Buffer.concat(chunks, size))
      .trimEnd();
    const line = text.slice(text.lastIndexOf("\n") + 1);
    reply = JSON.parse(line);
  } catch {
    return malformed;
  }

  // An overflow reply may arrive before the daemon knows the request id.
  const overflow =
    reply?.id === 0 && reply.kind === "error" && reply.error === "busy";

  if (!reply || (!overflow && reply.id !== request.id)) return malformed;
  if (reply.version !== PROTOCOL_VERSION) return refuse("protocol_version");

  if (reply.kind === "error") {
    if (typeof reply.error !== "string") return malformed;
    return refuse(REASONS.has(reply.error) ? reply.error : "daemon_error");
  }

  if (reply.kind !== request.kind) return malformed;
  return { ok: true, reply };
}

// Start the sole timer before spawning, and settle without waiting for a
// child to close after it has been killed.
function forward(request) {
  const line = JSON.stringify(request) + "\n";

  if (Buffer.byteLength(line) > MAX_FRAME_BYTES) {
    return Promise.resolve(refuse("daemon_error"));
  }

  return new Promise((resolve) => {
    let child;
    let settled = false;
    let pipeError = false;
    const chunks = [];
    let size = 0;
    const timer = setTimeout(() => stop(refuse("timeout")), BUDGET_MS);

    function finish(result) {
      if (settled) return false;

      settled = true;
      clearTimeout(timer);
      resolve(result);

      return true;
    }

    function stop(result) {
      if (!finish(result) || !child) return;

      try {
        child.kill("SIGKILL");
      } catch {
        // The denial is already settled; a kill error cannot allow a call.
      }
    }

    function failed() {
      stop(refuse("daemon_error"));
    }

    function spawnFailed(error) {
      if (error?.code === "ENOENT") {
        finish(refuse("hook_missing"));
        return;
      }

      failed();
    }

    // A pipe can fail before stdout delivers the reply.
    function notePipeError() {
      pipeError = true;
    }

    try {
      child = spawn(HOOK_BIN, ["--plugin", PLUGIN_DIR], {
        stdio: ["pipe", "pipe", "ignore"],
      });
      child.on("error", spawnFailed);
      child.stdout.on("error", notePipeError);
      child.stdin.on("error", notePipeError);
      child.stdout.on("data", (chunk) => {
        if (settled) return;

        size += chunk.length;
        if (size > MAX_FRAME_BYTES) {
          stop(refuse("malformed_reply"));
          return;
        }

        chunks.push(chunk);
      });
      child.once("close", (code) => {
        if (settled) return;

        const result =
          code !== 0 || (pipeError && size === 0)
            ? refuse("daemon_error")
            : readReply(request, chunks, size);
        finish(result);
      });
      child.stdin.end(line);
    } catch (error) {
      if (child) failed();
      else spawnFailed(error);
    }
  });
}

function record(call, id) {
  const path = process.env.TACK_RECORDER;

  if (path) appendFileSync(path, JSON.stringify({ call, id }) + "\n");
}

function block(reason) {
  return { block: true, reason: "tack: " + reason };
}

function toolError(reason) {
  return {
    content: [{ type: "text", text: "tack: " + reason }],
    details: {},
    isError: true,
  };
}

export default function register(pi) {
  let sequence = 0;
  let loaded = false;

  function nextId() {
    sequence = (sequence + 1) % Number.MAX_SAFE_INTEGER;
    return sequence;
  }

  async function guardBash(event) {
    try {
      if (event.toolName !== "bash") return;

      const command = event.input?.command;
      if (typeof command !== "string") return;

      const id = nextId();
      const result = await forward({
        kind: "hook",
        id,
        version: PROTOCOL_VERSION,
        hook: "toolBefore",
        call: {
          tool: "shell",
          name: "Bash",
          input: { command },
          session_id: null,
        },
      });

      if (!result.ok) return block(result.reason);

      const outcome = result.reply.outcome;
      if (outcome?.kind === "allow") {
        record("bash", id);
        return;
      }

      if (outcome?.kind === "deny" && typeof outcome.reason === "string") {
        record("bash", id);
        return block(outcome.reason);
      }

      return block("malformed_reply");
    } catch {
      return block("daemon_error");
    }
  }

  async function guardStatus(_toolCallId, params) {
    try {
      if (
        !params ||
        typeof params !== "object" ||
        Array.isArray(params) ||
        Object.keys(params).length !== 0
      ) {
        return toolError("malformed");
      }

      const id = nextId();
      const result = await forward({
        kind: "tool",
        id,
        version: PROTOCOL_VERSION,
        name: "guard_status",
        input: {},
      });

      if (!result.ok) return toolError(result.reason);

      const content = result.reply.content;
      const item =
        Array.isArray(content) && content.length === 1 ? content[0] : null;

      if (item?.kind !== "text" || item.text !== STATUS) {
        return toolError("malformed_reply");
      }

      record("guard_status", id);

      return { content: [{ type: "text", text: item.text }], details: {} };
    } catch {
      return toolError("daemon_error");
    }
  }

  pi.on("tool_call", guardBash);
  pi.registerTool({
    name: "guard_status",
    label: "guard_status",
    description: "Reports whether the tack daemon is running",
    parameters: { type: "object", properties: {} },
    execute: guardStatus,
  });
  pi.on("session_start", () => {
    if (loaded) return;

    loaded = true;
    pi.appendEntry("tack-loaded", {});
  });
}
